/**
 * Renders `core-tokens.ts` from the core's `tokens.json` (task A2) — a pure
 * function shared by `scripts/sync-tokens.mjs` (which writes the file) and
 * `tokens.test.mjs` (which proves the committed file is its projection).
 */
export function renderCoreTokensTs(json, source) {
  return [
    '/**',
    " * GENERATED by scripts/sync-tokens.mjs from the core's tokens/tokens.json (task A2) — never edit by hand.",
    ` * Source: ${source}`,
    ' */',
    `export const core = ${JSON.stringify(json, null, 2)} as const`,
    '',
  ].join('\n')
}
